iterations.reply:
Two notes on the choices below:

- `PublishedDigest` has no `text` field, so I used its `date` field as the query value, percent-encoded.
- `fetch` returns its failures as a value, so I ignore the result and the output never depends on the enrichment call.

I also made `recorded` count only the ids newly marked seen, and only when `published` is true. That is my reading of the node's intent, since the contract doesn't specify it.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_rw};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch: result is intentionally ignored so output is unaffected.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                let key = format!("seen:{}", id);
                if state_rw::get(&key).is_none() {
                    state_rw::put(&key, "1");
                    recorded += 1;
                }
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

